package org.securemail.identity;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.securemail.ecosystem.protocol.IdentityProtocol;
import java.nio.file.*;
import java.security.*;
import java.security.spec.PKCS8EncodedKeySpec;
import java.io.*;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class IdentityMainTest {
    @TempDir Path temp;
    @Test void actualOperatorCliBootstrapUsesOnlyPublicChallengeAndProof()throws Exception {
        Path home=temp.resolve("service home");IdentityMain.main(new String[]{"init","--home",home.toString()});assertTrue(Files.size(home.resolve("service.key"))>0);assertThrows(IOException.class,()->IdentityMain.main(new String[]{"init","--home",home.toString()}));
        KeyPair service;byte[] encoded=Files.readAllBytes(home.resolve("service.key"));try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(encoded))){assertEquals("AEGIS-IDENTITY-SERVICE/v1",in.readUTF());byte[] pub=in.readNBytes(in.readInt()),priv=in.readNBytes(in.readInt());service=new KeyPair(IdentityProtocol.publicKey(pub),KeyFactory.getInstance("Ed25519").generatePrivate(new PKCS8EncodedKeySpec(priv)));Arrays.fill(priv,(byte)0);}Arrays.fill(encoded,(byte)0);
        KeyPair root=KeyPairGenerator.getInstance("Ed25519").generateKeyPair(),device=KeyPairGenerator.getInstance("Ed25519").generateKeyPair(),recovery=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();String account=IdentityProtocol.id(root.getPublic().getEncoded()),audience=IdentityProtocol.id(service.getPublic().getEncoded());byte[] audit=Files.readAllBytes(home.resolve("audit.key"));try(IdentityStore store=new IdentityStore(home.resolve("identity.db"),service,audit,Clock.systemUTC())){long t=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();byte[] b=IdentityProtocol.registration(audience,root.getPublic().getEncoded(),device.getPublic().getEncoded(),recovery.getPublic().getEncoded(),"Владелец",t,nonce);store.register(root.getPublic().getEncoded(),device.getPublic().getEncoded(),recovery.getPublic().getEncoded(),"Владелец",t,nonce,IdentityProtocol.sign(root.getPrivate(),b),IdentityProtocol.sign(device.getPrivate(),b));}
        Path challenge=temp.resolve("challenge.json");IdentityMain.main(new String[]{"owner","bootstrap","--home",home.toString(),"--account-id",account,"--challenge",challenge.toString()});Map<String,Object> c=IdentityJson.parse(Files.readAllBytes(challenge));assertEquals(audience,c.get("audience"));byte[] payload=IdentityProtocol.unb64((String)c.get("proofBytes"),1024);assertArrayEquals(IdentityProtocol.ownerBootstrap(audience,account,(String)c.get("challenge"),(Long)c.get("expiresAt")),payload);
        Path proof=temp.resolve("proof.json");Files.write(proof,IdentityJson.bytes(Map.of("audience",audience,"accountId",account,"challenge",c.get("challenge"),"signature",IdentityProtocol.b64(IdentityProtocol.sign(root.getPrivate(),payload)))));IdentityMain.main(new String[]{"owner","bootstrap","--home",home.toString(),"--account-id",account,"--proof",proof.toString()});assertThrows(IdentityException.class,()->IdentityMain.main(new String[]{"owner","bootstrap","--home",home.toString(),"--account-id",account,"--proof",proof.toString()}));IdentityMain.main(new String[]{"inspect","--home",home.toString()});try(IdentityStore store=new IdentityStore(home.resolve("identity.db"),service,audit,Clock.systemUTC())){assertEquals(true,store.profile(account).get("ownerBadge"));assertTrue(store.verifyAudit());}Arrays.fill(audit,(byte)0);
    }
    @Test void operatorRelayAllowAndRevokeUseOnlyPinnedPublicFile()throws Exception {Path home=temp.resolve("relay-service");IdentityMain.main(new String[]{"init","--home",home.toString()});KeyPair relay=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();Path publicFile=temp.resolve("relay-public.txt");Files.writeString(publicFile,IdentityProtocol.b64(relay.getPublic().getEncoded())+"\n");String fingerprint=IdentityProtocol.id(relay.getPublic().getEncoded());assertThrows(IdentityException.class,()->IdentityMain.main(new String[]{"service","relay","allow","--home",home.toString(),"--public",publicFile.toString(),"--fingerprint","0".repeat(64)}));IdentityMain.main(new String[]{"service","relay","allow","--home",home.toString(),"--public",publicFile.toString(),"--fingerprint",fingerprint});try(java.sql.Connection sql=java.sql.DriverManager.getConnection("jdbc:sqlite:"+home.resolve("identity.db"));java.sql.Statement query=sql.createStatement();java.sql.ResultSet r=query.executeQuery("SELECT purpose,active FROM trusted_services")){assertTrue(r.next());assertEquals("RELAY_MANAGED_QUERY",r.getString(1));assertEquals(1,r.getInt(2));assertFalse(r.next());}IdentityMain.main(new String[]{"service","relay","revoke","--home",home.toString(),"--fingerprint",fingerprint});try(java.sql.Connection sql=java.sql.DriverManager.getConnection("jdbc:sqlite:"+home.resolve("identity.db"));java.sql.Statement query=sql.createStatement();java.sql.ResultSet r=query.executeQuery("SELECT active FROM trusted_services")){assertTrue(r.next());assertEquals(0,r.getInt(1));}}
    @Test void unrecognizedOptionsAndSymlinkHomesRefused()throws Exception {assertThrows(IllegalArgumentException.class,()->IdentityMain.main(new String[]{"init","--execute","evil"}));Path target=temp.resolve("real");Files.createDirectories(target);Path link=temp.resolve("link");Files.createSymbolicLink(link,target);assertThrows(IOException.class,()->IdentityMain.main(new String[]{"init","--home",link.toString()}));}
}
